<?php require_once '../config/config.php';require_admin();$title='Manage Rooms | '.APP_NAME;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action'];if($action==='add'){$s=db()->prepare("INSERT INTO rooms(room_number,room_type_id,price,image,status) VALUES(?,?,?,?,?)");$s->execute([trim($_POST['room_number']),(int)$_POST['room_type_id'],(float)$_POST['price'],trim($_POST['image']),'available']);flash('success','Room added.');}elseif($action==='status'){$s=db()->prepare("UPDATE rooms SET status=? WHERE id=?");$s->execute([$_POST['status'],(int)$_POST['id']]);flash('success','Room status updated.');}redirect('rooms.php');}
$types=db()->query("SELECT * FROM room_types")->fetchAll();$rooms=db()->query("SELECT r.*,rt.name type_name FROM rooms r JOIN room_types rt ON rt.id=r.room_type_id ORDER BY r.room_number")->fetchAll();require '../partials_header.php';?>
<div class="admin-nav"><div class="container"><strong>Admin Panel</strong><a href="index.php">Dashboard</a><a href="rooms.php">Rooms</a><a href="bookings.php">Bookings</a></div></div><div class="page"><div class="container"><h1>Room Inventory</h1><div class="panel"><h2>Add Room</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="add"><div class="form-grid"><div><label>Room No.</label><input name="room_number" required></div><div><label>Type</label><select name="room_type_id"><?php foreach($types as $t):?><option value="<?=$t['id']?>"><?=e($t['name'])?></option><?php endforeach;?></select></div><div><label>Price/night</label><input type="number" name="price" required></div><div><label>Image URL</label><input name="image"></div></div><br><button class="btn orange">Add Room</button></form></div><br><div class="panel table-wrap"><table class="table"><tr><th>Room</th><th>Type</th><th>Price</th><th>Status</th><th>Change</th></tr><?php foreach($rooms as $r):?><tr><td><?=e($r['room_number'])?></td><td><?=e($r['type_name'])?></td><td>NPR <?=number_format((float)$r['price'])?></td><td><?=e($r['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" onchange="this.form.submit()"><option value="available" <?=$r['status']==='available'?'selected':''?>>Available</option><option value="maintenance" <?=$r['status']==='maintenance'?'selected':''?>>Maintenance</option></select></form></td></tr><?php endforeach;?></table></div></div></div><?php require '../partials_footer.php'; ?>
